public class ThreadingDemo {
    public static void main(String[] args) {
        // Approach 1: Extending the Thread class (Tight coupling)
        Thread threadStyle = new WorkerThread();
        threadStyle.start();

        // Approach 2: Implementing the Runnable interface (Loose coupling, preferred)
        Runnable task = () -> System.out.println("Running via Runnable: " + Thread.currentThread().getName());
        Thread runnableStyle = new Thread(task);
        runnableStyle.start();
    }

    private static class WorkerThread extends Thread {
        @Override
        public void run() {
            System.out.println("Running via Thread subclass: " + Thread.currentThread().getName());
        }
    }
}
